mapper.select:
SELECT 
FROM trading_strategy
WHERE account_id = #{accountId}
  AND symbol = #{symbol}
  AND strategy_type = 'PRICE_TARGET'
  AND side = #{side}
  AND target_price = #{targetPrice}
  AND quantity = #{quantity}
  AND status = 'ACTIVE'
ORDER BY strategy_id
LIMIT 1

SELECT 
FROM trading_strategy
WHERE strategy_id = #{strategyId}
  AND account_id = #{accountId}

mapper.delete:
DELETE FROM trading_strategy
WHERE strategy_id = #{strategyId}
  AND account_id = #{accountId}

mapper.update:
UPDATE trading_strategy
SET last_state = COALESCE(#{state}, last_state),
    last_price = #{price},
    last_evaluated_at = #{at}
WHERE strategy_id = #{strategyId}
  AND status = 'ACTIVE'

UPDATE trading_strategy
SET consecutive_failures = consecutive_failures + 1
WHERE strategy_id = #{strategyId}

mapper.insert:
INSERT INTO strategy_execution (strategy_id, event_id, signal, price, quantity, status, reason)
SELECT #{strategyId}, #{eventId}, #{signal}, #{price}, #{quantity}, #{status}, #{reason}
FROM trading_strategy
WHERE strategy_id = #{strategyId}
  AND status = 'ACTIVE'

mapper.update:
UPDATE strategy_execution
SET status = #{status},
    order_id = #{orderId},
    reason = #{reason}
WHERE execution_id = #{executionId}
  AND status = 'PENDING'

mapper.select:
SELECT COUNT(*)
FROM strategy_execution
WHERE strategy_id = #{strategyId}
  AND status IN ('PENDING', 'PLACED')
  AND created_at >= #{since}

SELECT 'ORD-' || order_id
FROM orders
WHERE idempotency_key = #{idempotencyKey}
